class Solution {
    int m, n;
    int dirs[4][2] = {{0,1},{0,-1},{1,0},{-1,0}};
    vector<vector<int>> disc, low;
    vector<vector<bool>> isArt;
    int timer;
    const vector<vector<int>>* G;
    void dfs(int r, int c, int pr, int pc){
        disc[r][c] = low[r][c] = ++timer;
        int children = 0;
        const auto& grid = *G;
        for (auto& d : dirs){
            int nr = r + d[0], nc = c + d[1];
            if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
            if (grid[nr][nc] != 1) continue;
            if (disc[nr][nc] == 0){
                children++;
                dfs(nr, nc, r, c);
                low[r][c] = min(low[r][c], low[nr][nc]);
                if (pr != -1 && low[nr][nc] >= disc[r][c]) isArt[r][c] = true;
            } else if (!(nr == pr && nc == pc)){
                low[r][c] = min(low[r][c], disc[nr][nc]);
            }
        }
        if (pr == -1 && children > 1) isArt[r][c] = true;
    }
public:
    int minDays(vector<vector<int>>& grid) {
        m = grid.size(); n = grid[0].size();
        int landCount = 0;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (grid[i][j] == 1) landCount++;
        int islands = 0;
        vector<vector<bool>> visited(m, vector<bool>(n, false));
        for (int i = 0; i < m; i++){
            for (int j = 0; j < n; j++){
                if (grid[i][j] == 1 && !visited[i][j]){
                    islands++;
                    stack<pair<int,int>> st;
                    st.push({i, j});
                    visited[i][j] = true;
                    while (!st.empty()){
                        auto [r, c] = st.top(); st.pop();
                        for (auto& d : dirs){
                            int nr = r + d[0], nc = c + d[1];
                            if (nr >= 0 && nr < m && nc >= 0 && nc < n &&
                                grid[nr][nc] == 1 && !visited[nr][nc]){
                                visited[nr][nc] = true;
                                st.push({nr, nc});
                            }
                        }
                    }
                }
            }
        }
        if (islands != 1) return 0;
        if (landCount == 1) return 1;

        disc.assign(m, vector<int>(n, 0));
        low.assign(m, vector<int>(n, 0));
        isArt.assign(m, vector<bool>(n, false));
        timer = 0;
        G = &grid;

        for (int i = 0; i < m; i++){
            for (int j = 0; j < n; j++){
                if (grid[i][j] == 1){
                    dfs(i, j, -1, -1);
                    for (int a = 0; a < m; a++)
                        for (int b = 0; b < n; b++)
                            if (isArt[a][b]) return 1;
                    return 2;
                }
            }
        }
        return 2;
    }
};
